#[cfg(test)]
mod tests {
    #![allow(dead_code)]
    #![allow(unused_imports)]

    use super::*;
    use crate::document::document_controller;
    use crate::document::dtos::CreateDocumentDto;
    use crate::root::dtos::CreateRootDto;
    use crate::root::root_controller;
    use common::database::db_context::DbContext;
    use common::event::EventHub;
    use common::types::EntityId;
    use common::undo_redo::UndoRedoManager;
    use std::sync::Arc;

    struct TestContext {
        db: DbContext,
        hub: Arc<EventHub>,
        undo: UndoRedoManager,
    }

    impl TestContext {
        fn new() -> Self {
            let db = DbContext::new().expect("Failed to create in-memory DB");
            let hub = Arc::new(EventHub::new());
            let mut undo = UndoRedoManager::new();
            undo.set_event_hub(&hub);
            TestContext { db, hub, undo }
        }
    }

    /// Build the ownership chain and return the direct owner's id.
    fn create_owner_chain(ctx: &mut TestContext) -> EntityId {
        let root =
            root_controller::create_orphan(&ctx.db, &ctx.hub, &CreateRootDto::default()).unwrap();
        let document = document_controller::create(
            &ctx.db,
            &ctx.hub,
            &mut ctx.undo,
            None,
            &CreateDocumentDto::default(),
            root.id,
            -1,
        )
        .unwrap();
        document.id
    }

    /// Create an entity using create_orphan.
    fn create_one(ctx: &mut TestContext) -> FrameDto {
        create_orphan(
            &ctx.db,
            &ctx.hub,
            &mut ctx.undo,
            None,
            &CreateFrameDto::default(),
        )
        .unwrap()
    }

    // -----------------------------------------------------------------------
    // create_orphan + get
    // -----------------------------------------------------------------------

    #[test]
    fn test_create_orphan_and_get() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        assert!(created.id > 0);

        let fetched = get(&ctx.db, &created.id).unwrap();
        assert!(fetched.is_some());
        assert_eq!(fetched.unwrap().id, created.id);
    }

    // -----------------------------------------------------------------------
    // get nonexistent
    // -----------------------------------------------------------------------

    #[test]
    fn test_get_nonexistent() {
        let ctx = TestContext::new();
        assert!(get(&ctx.db, &999999).unwrap().is_none());
    }

    // -----------------------------------------------------------------------
    // get_all
    // -----------------------------------------------------------------------

    #[test]
    fn test_get_all() {
        let mut ctx = TestContext::new();
        create_one(&mut ctx);
        let all = get_all(&ctx.db).unwrap();
        assert!(!all.is_empty());
    }

    // -----------------------------------------------------------------------
    // get_multi
    // -----------------------------------------------------------------------

    #[test]
    fn test_get_multi() {
        let mut ctx = TestContext::new();
        let a = create_one(&mut ctx);
        let results = get_multi(&ctx.db, &[a.id, 999999]).unwrap();
        assert_eq!(results.len(), 2);
        assert!(results[0].is_some());
        assert!(results[1].is_none());
    }

    // -----------------------------------------------------------------------
    // update
    // -----------------------------------------------------------------------

    #[test]
    fn test_update() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        let update_dto: UpdateFrameDto = created.into();
        let updated = update(&ctx.db, &ctx.hub, &mut ctx.undo, None, &update_dto).unwrap();
        assert_eq!(updated.id, update_dto.id);
    }

    // -----------------------------------------------------------------------
    // remove
    // -----------------------------------------------------------------------

    #[test]
    fn test_remove() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        remove(&ctx.db, &ctx.hub, &mut ctx.undo, None, &created.id).unwrap();
        assert!(get(&ctx.db, &created.id).unwrap().is_none());
    }

    // -----------------------------------------------------------------------
    // remove_multi
    // -----------------------------------------------------------------------

    #[test]
    fn test_remove_multi() {
        let mut ctx = TestContext::new();
        let a = create_one(&mut ctx);
        remove_multi(&ctx.db, &ctx.hub, &mut ctx.undo, None, &[a.id]).unwrap();
        assert!(get(&ctx.db, &a.id).unwrap().is_none());
    }

    // -----------------------------------------------------------------------
    // create with owner
    // -----------------------------------------------------------------------

    #[test]
    fn test_create_with_owner() {
        let mut ctx = TestContext::new();
        let owner_id = create_owner_chain(&mut ctx);
        let created = create(
            &ctx.db,
            &ctx.hub,
            &mut ctx.undo,
            None,
            &CreateFrameDto::default(),
            owner_id,
            -1,
        )
        .unwrap();
        assert!(created.id > 0);
        let fetched = get(&ctx.db, &created.id).unwrap();
        assert!(fetched.is_some());
    }

    // -----------------------------------------------------------------------
    // undo create_orphan
    // -----------------------------------------------------------------------

    #[test]
    fn test_create_orphan_undo() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        assert!(get(&ctx.db, &created.id).unwrap().is_some());
        ctx.undo.undo(None).unwrap();
        assert!(get(&ctx.db, &created.id).unwrap().is_none());
    }

    // -----------------------------------------------------------------------
    // undo remove
    // -----------------------------------------------------------------------

    #[test]
    fn test_remove_undo() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        remove(&ctx.db, &ctx.hub, &mut ctx.undo, None, &created.id).unwrap();
        assert!(get(&ctx.db, &created.id).unwrap().is_none());
        ctx.undo.undo(None).unwrap();
        assert!(get(&ctx.db, &created.id).unwrap().is_some());
    }

    // -----------------------------------------------------------------------
    // relationship: get default
    // -----------------------------------------------------------------------

    #[test]
    fn test_get_relationship_default() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        let rel_ids =
            get_relationship(&ctx.db, &created.id, &FrameRelationshipField::Blocks).unwrap();
        assert!(rel_ids.is_empty());
    }

    // -----------------------------------------------------------------------
    // relationship: count default
    // -----------------------------------------------------------------------

    #[test]
    fn test_get_relationship_count_default() {
        let mut ctx = TestContext::new();
        let created = create_one(&mut ctx);
        let count =
            get_relationship_count(&ctx.db, &created.id, &FrameRelationshipField::Blocks).unwrap();
        assert_eq!(count, 0);
    }

    // -----------------------------------------------------------------------
    // relationship: undo and redo
    // -----------------------------------------------------------------------

    fn blocks_of(ctx: &TestContext, frame: EntityId) -> Vec<EntityId> {
        get_relationship(&ctx.db, &frame, &FrameRelationshipField::Blocks).unwrap()
    }

    /// The undo of a set or a move puts back that one list and nothing else, keeps no
    /// savepoint, and survives a second undo and redo.
    #[test]
    fn test_relationship_undo_redo_touches_only_that_list() {
        use crate::block::block_controller;
        use crate::block::dtos::CreateBlockDto;
        use common::undo_redo::UNTRACKED_STACK_ID;

        let mut ctx = TestContext::new();
        let frame = create_one(&mut ctx).id;
        let mut block = || {
            block_controller::create_orphan(
                &ctx.db,
                &ctx.hub,
                &mut ctx.undo,
                None,
                &CreateBlockDto::default(),
            )
            .unwrap()
            .id
        };
        let (a, b, c) = (block(), block(), block());

        set_relationship(
            &ctx.db,
            &ctx.hub,
            &mut ctx.undo,
            None,
            &FrameRelationshipDto {
                id: frame,
                field: FrameRelationshipField::Blocks,
                right_ids: vec![a, b, c],
            },
        )
        .unwrap();
        move_relationship(
            &ctx.db,
            &ctx.hub,
            &mut ctx.undo,
            None,
            &frame,
            &FrameRelationshipField::Blocks,
            &[c],
            0,
        )
        .unwrap();
        assert_eq!(blocks_of(&ctx, frame), vec![c, a, b]);

        // A write no undo history records, made after both.
        let untracked = create_orphan(
            &ctx.db,
            &ctx.hub,
            &mut ctx.undo,
            Some(UNTRACKED_STACK_ID),
            &CreateFrameDto::default(),
        )
        .unwrap()
        .id;

        for cycle in 1..=2 {
            ctx.undo.undo(None).unwrap();
            assert_eq!(
                blocks_of(&ctx, frame),
                vec![a, b, c],
                "undo of the move, {cycle}"
            );
            ctx.undo.undo(None).unwrap();
            assert!(
                blocks_of(&ctx, frame).is_empty(),
                "undo of the set, {cycle}"
            );
            assert!(
                get(&ctx.db, &untracked).unwrap().is_some(),
                "the undo puts back the list, not the whole store"
            );
            ctx.undo.redo(None).unwrap();
            assert_eq!(
                blocks_of(&ctx, frame),
                vec![a, b, c],
                "redo of the set, {cycle}"
            );
            ctx.undo.redo(None).unwrap();
            assert_eq!(
                blocks_of(&ctx, frame),
                vec![c, a, b],
                "redo of the move, {cycle}"
            );
        }
        assert_eq!(ctx.db.get_store().savepoint_count(), 0);
    }
}
